216	
217	        if (event.fidelity === LearningFidelity.PATTERN && !permissions.allowPatternExtraction) return { target: TruthClass.POLICY_DENIED, type: 'GATED_PATTERN_EXTRACTION' };
218	        if (event.fidelity === LearningFidelity.INVARIANT && !permissions.allowInvariantCompilation) return { target: TruthClass.POLICY_DENIED, type: 'GATED_INVARIANT_COMPILATION' };
219	        if (event.fidelity === LearningFidelity.PEDAGOGY && !permissions.allowPedagogy) return { target: TruthClass.POLICY_DENIED, type: 'GATED_PEDAGOGY' };
